(()=>{const A='#e1c08e',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`.fx-progress{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fx-progress i{display:block;height:100%;width:0;background:${A};box-shadow:0 0 14px ${A}}.fx-projector-light{position:fixed;left:50%;top:45%;width:2px;height:2px;border-radius:50%;background:#fff;box-shadow:0 0 120px 55px ${A}18;pointer-events:none;z-index:0;animation:lamp 3s ease-in-out infinite}.fx-reveal{opacity:0;transform:translateY(35px) scale(.985);transition:opacity 1s ease,transform 1s cubic-bezier(.2,.8,.2,1)}.fx-visible{opacity:1!important;transform:none!important}@keyframes lamp{50%{opacity:.55;transform:scale(1.25)}}`;b.appendChild(s);const p=document.createElement('div');p.className='fx-progress';p.innerHTML='<i></i>';b.appendChild(p);const l=document.createElement('div');l.className='fx-projector-light';b.appendChild(l);document.querySelectorAll('section').forEach(s=>s.classList.add('fx-reveal'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('fx-visible');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fx-reveal').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;p.firstElementChild.style.width=(max?scrollY/max*100:0)+'%'})})();